namespace gem5
{

// CHAOSPTW — page-table-walker readout fault injector (D3).
//
// Core 179's D3 signature (MICROARCH_SUPPLEMENT §2.4): 73 transient
// translation-fault warnings on VALID static mappings (ESR 0x96000044 /
// 0x96000004) — the hardware page-table walker transiently mis-read a
// page-table entry, the immediate AT-retry succeeded. This is the PTW
// readout data-path, sibling to D1 (load data path) and D2 (address path).
//
// This injector hooks the ARM table walker's doLongDescriptor (and the
// 32-bit doL1/doL2 descriptor paths) to bit-flip a freshly-fetched
// descriptor with probability `probability`. If the flip clears the valid
// bit (or makes the entry look invalid), the walker reports a translation
// fault — reproducing the spurious-fault symptom. `ptwEcc` knob models
// whether the PTW array has ECC (H7: ECC-on should suppress spurious).
//
// FAITHFULNESS (FI_DESIGN_SUPPLEMENT §5): gem5's ARM walker is a simplified
// model of TSV110's PTW; the corruption lands on the in-memory PTE read,
// matching where D3 sits physically (PTW readout return path). Declared
// as a modeling limitation.
class CHAOSPTW : public SimObject
{
  public:
    CHAOSPTW(const CHAOSPTWParams &p);
    ~CHAOSPTW();
    // Called from table_walker.cc after a descriptor (PTE) is fetched and
    // byte-swapped, BEFORE it is evaluated. If the RNG fires, flips bits in
    // *data (an 8-byte or 4-byte descriptor). Returns the (possibly
    // corrupted) descriptor value.
    void corruptDescriptor(uint8_t *data, unsigned size, Addr desc_addr);
  private:
    float probability;
    int num_bits;          // bits to flip when faultMask=0
    unsigned fault_mask;   // explicit bitmask (0 = random num_bits)
    int byte_offset;       // -1 = random byte in [0,size-1]
    bool ptw_ecc;          // model PTW array ECC (H7 knob)
    Cycles first_clock, last_clock;
    uint64_t max_faults, faults_injected_count;
    uint64_t rng_seed;
    bool write_log;
    // CHAOSPTW is not CPU-bound (it hooks the MMU walker, which may outlive
    // any single CPU). We log via simout and use curTick() for timing.
    std::mt19937 rng;
    std::random_device rd;
    OutputStream *log_stream;
    struct Stats : public statistics::Group {
        statistics::Scalar numFaultsInjected;
        statistics::Scalar numSpuriousFaults;   // flips that produced an invalid PTE
        statistics::Scalar numBenignFlips;       // flips the PTE survived (ECC-corrected or no-op)
        Stats(statistics::Group *parent);
    };
    std::unique_ptr<Stats> stats;
    int generateRandomMask(int bits_to_change);
    void writeLog(Addr desc_addr, uint64_t orig, uint64_t corr, bool became_invalid);
};

} // namespace gem5
#endif // __ARCH_ARM_CHAOS_PTW_HH__
