    int
    CHAOSPTW::generateRandomMask(int bits_to_change)
    {
        int mask = 0;
        std::uniform_int_distribution<int> bitDist(0, 7);
        while (bits_to_change-- > 0) mask |= (1 << bitDist(rng));
        return mask;
    }

    void
    CHAOSPTW::writeLog(Addr desc_addr, uint64_t orig, uint64_t corr,
                       bool became_invalid)
    {
