        if (off >= (int)size) off = (int)size - 1;

        int mask = fault_mask ? (int)(fault_mask & 0xff)
                              : generateRandomMask(num_bits);

        uint64_t orig = 0;
        std::memcpy(&orig, data, size);
        data[off] ^= (uint8_t)mask;
        uint64_t corr = 0;
        std::memcpy(&corr, data, size);

